// Per-column sum: walk row by row so the inner loop strides by 1 double
// (contiguous), then accumulate into the per-column output. The previous
// column-major walk used a stride of `cols_` doubles per access, blowing
// the L1 cache on inputs larger than ~256x256.
std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    for (std::size_t r = 0; r < rows_; ++r) {
        for (std::size_t c = 0; c < cols_; ++c) {
            result[c] += data_[r * cols_ + c];
        }
    }
    return result;
}

